mapper.select:
select count(distinct vma.id) FROM virtual_warehouse_allocation_detail vmad inner JOIN virtual_warehouse_allocation vma on vma.id = vmad.main_id and vma.is_deleted = false where vmad.is_deleted = false
and vma.status = #{params.status}
${params.permissionSql}

select vmad.sku_id, pd.sku_no, pd.name as productName, vmad.warehouse_id, vmad.warehouse_name, vmad.from_virtual_warehouse_id, vmad.from_virtual_warehouse_name, SUM(coalesce(vmad.qty,0)) as totalQty, SUM(CASE WHEN vwa.status = 'waitSubmit' and vwa.type = 'allocation' THEN vmad.qty else 0 end) as submitAddAllocationQty, SUM(CASE WHEN vwa.status = 'handle' and vwa.type = 'allocation' THEN vmad.qty else 0 end) as handleAddAllocationQty, SUM(CASE WHEN vwa.status = 'waitSubmit' and vwa.type = 'cancel' THEN vmad.qty else 0 end) as submitCancelAllocationQty, SUM(CASE WHEN vwa.status = 'handle' and vwa.type = 'cancel' THEN vmad.qty else 0 end) as handleCancelAllocationQty from virtual_warehouse_allocation vwa inner join virtual_warehouse_allocation_detail vmad on vwa.id = vmad.main_id and vmad.is_deleted = false left join product_detail pd on vmad.sku_id = pd.id and pd.is_deleted = false ${params.sqlMap.default} and vwa.is_deleted = false and vwa.status != 'invalid' and vwa.type != 'transfer'
${params.permissionSql}
group by vmad.sku_id,pd.sku_no,pd.name,vmad.warehouse_id,vmad.warehouse_name,vmad.from_virtual_warehouse_id,vmad.from_virtual_warehouse_name

mapper.sql:
WITH inventory_data AS ( SELECT sku_id, warehouse_id, SUM(qty) AS realQty FROM inventory WHERE is_deleted = FALSE AND dict_inventory_status IN ('usable', 'frozen') GROUP BY sku_id, warehouse_id ), virtual_inventory_data AS ( SELECT sku_id, warehouse_id, SUM(qty) AS distributionQty FROM virtual_inventory WHERE is_deleted = FALSE GROUP BY sku_id, warehouse_id ), virtual_inventory_usable AS ( SELECT sku_id, warehouse_id, virtual_warehouse_id, SUM(qty) AS toVirtualUsableQty FROM virtual_inventory WHERE is_deleted = FALSE AND dict_inventory_status = 'usable' GROUP BY sku_id, warehouse_id, virtual_warehouse_id ), virtual_inventory_stats AS ( SELECT sku_id, warehouse_id, virtual_warehouse_id, SUM(qty) AS virtualRealQty, SUM(CASE WHEN dict_inventory_status = 'usable' THEN qty ELSE 0 END) AS fromVirtualUsableQty, SUM(CASE WHEN dict_inventory_status = 'frozen' THEN qty ELSE 0 END) AS fromVirtualFrozenQty FROM virtual_inventory WHERE is_deleted = FALSE GROUP BY sku_id, warehouse_id, virtual_warehouse_id ) SELECT vm.*, CASE WHEN vm.status = 'waitSubmit' AND vm.type = 'allocation' AND isVirtualScarce THEN vm.totalMergeQty - vm.unDistributionQty WHEN vm.status = 'waitSubmit' AND vm.type = 'transfer' AND isVirtualScarce THEN vm.totalMergeQty - vm.fromVirtualUsableQty WHEN vm.status = 'waitSubmit' AND vm.type = 'cancel' AND isVirtualScarce THEN vm.totalMergeQty - vm.fromVirtualUsableQty ELSE 0 END AS virtualScarceQty FROM ( SELECT vma.id, vmad.id AS detailId, vma.code, vma.status, vma.type, vma.remark, vmad.sku_id AS skuId, vmad.sku_no AS skuNo, vmad.product_name AS productName, vmad.warehouse_id AS warehouseId, vmad.warehouse_name AS warehouseName, vmad.from_virtual_warehouse_id AS fromVirtualWarehouseId, vmad.from_virtual_warehouse_name AS fromVirtualWarehouseName, vmad.qty, vmad.to_virtual_warehouse_id AS toVirtualWarehouseId, vmad.to_virtual_warehouse_name AS toVirtualWarehouseName, vmad.finish_description AS finishDescription, vma.invalid_description AS invalidDescription, vmad.sync_status AS syncStatus, vmad.create_user_id AS createUserId, vmad.create_user_name AS createUserName, vmad.create_time AS createTime, vmad.update_user_id AS updateUserId, vmad.update_user_name AS updateUserName, vmad.update_time AS updateTime, vmad.third_code AS thirdCode, vmad.sys_type AS sysType, vmad.sys_type_name AS sysTypeName, vma.is_statistics AS isStatistics, COALESCE(iv.realQty, 0) AS realQty, COALESCE(vi.distributionQty, 0) AS distributionQty, COALESCE(vit.toVirtualUsableQty, 0) AS toVirtualWarehouseUsableQty, COALESCE(vif.virtualRealQty, 0) AS virtualRealQty, COALESCE(vif.fromVirtualUsableQty, 0) AS fromVirtualUsableQty, vim.totalMergeQty, COALESCE(iv.realQty, 0) - COALESCE(vi.distributionQty, 0) AS unDistributionQty, CASE WHEN vma.status = 'waitSubmit' AND vma.type = 'allocation' THEN vim.totalMergeQty > COALESCE(iv.realQty, 0) - COALESCE(vi.distributionQty, 0) WHEN vma.status = 'waitSubmit' AND vma.type = 'transfer' THEN vim.totalMergeQty > COALESCE(vif.fromVirtualUsableQty, 0) WHEN vma.status = 'waitSubmit' AND vma.type = 'cancel' THEN vim.totalMergeQty > COALESCE(vif.fromVirtualUsableQty, 0) ELSE FALSE END AS isVirtualScarce FROM virtual_warehouse_allocation_detail vmad INNER JOIN virtual_warehouse_allocation vma ON vma.id = vmad.main_id AND vma.is_deleted = FALSE LEFT JOIN inventory_data iv ON vmad.sku_id = iv.sku_id AND vmad.warehouse_id = iv.warehouse_id LEFT JOIN virtual_inventory_data vi ON vmad.sku_id = vi.sku_id AND vmad.warehouse_id = vi.warehouse_id LEFT JOIN virtual_inventory_usable vit ON vmad.sku_id = vit.sku_id AND vmad.warehouse_id = vit.warehouse_id AND vmad.to_virtual_warehouse_id = vit.virtual_warehouse_id LEFT JOIN virtual_inventory_stats vif ON vmad.sku_id = vif.sku_id AND vmad.warehouse_id = vif.warehouse_id AND vmad.from_virtual_warehouse_id = vif.virtual_warehouse_id LEFT JOIN ( SELECT SUM(qty) AS totalMergeQty, main_id, sku_id, warehouse_id, to_virtual_warehouse_id, from_virtual_warehouse_id FROM virtual_warehouse_allocation_detail WHERE is_deleted = FALSE GROUP BY main_id, sku_id, warehouse_id, to_virtual_warehouse_id, from_virtual_warehouse_id ) vim ON vmad.main_id = vim.main_id AND vmad.sku_id = vim.sku_id AND vmad.warehouse_id = vim.warehouse_id AND vmad.to_virtual_warehouse_id = vim.to_virtual_warehouse_id AND vmad.from_virtual_warehouse_id = vim.from_virtual_warehouse_id where vmad.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vma.id desc,vmad.id asc ) vm where 1 = 1 and ${params.sqlMap.default}
